INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l1.far-fold','context','L1 · Far 远窗折叠','后台将更早对话折叠进 far_summary；对照现行 L2，冲突以 L2 为准，避免污染 system。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l1.interrupted-marker','context','L1 · 中断注记','装载历史时对 INTERRUPTED 的 assistant 消息折叠的中断状态注记；让后续轮次从 Near 感知上一轮被中断。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
