INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l2.audit','context','L2 · 状态矛盾审计','审阅用户 active L2；明确互斥/错误 → voidIds；暧昧可疑 → conflictIds；仅输出 JSON。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
