INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.memory.extract','context','Memory · KV 抽取','KV Memory 抽取：按 scope（user=用户级 / workspace=工作区级）识别可跨会话复用的结构化条目（含 todo）；v22 门禁——key 场景化（仅小写字母/数字/下划线）、background 必填、value 自解释非布尔孤值、完成即 void、宁缺毋滥。',1,0,1,143,'2026-08-23 03:21:00','2026-08-23 14:55:00');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('context.l3.material-header','context','L3 · 历史材料边界头','注入 L3 召回材料块时的 system 边界头；标明可能过期、非指令。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
