INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('conversation.title','title','会话 · 标题摘要','新对话/新任务首条消息时，用小模型提炼 15 字以内的中文短语标题。',1,0,1,1,'2026-08-08 01:41:48','2026-08-08 01:41:48');
INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('harness.worker','harness','Planner-Executor · Worker','Worker 单元执行薄层：单一职责（执行当前单元 + 任务摘要回传）；工具选型/沙箱要点/TaskBoard 等叠加层由 mode-overlay.react 注入。',1,0,1,131,'2026-08-15 06:16:19','2026-08-21 07:26:30');
