INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('intent.classifier.skill-agent','intent','意图收集 · 轨 A（Skill/Agent）','意图收集轨 A（fast/pro）：仅召回 agentIds/skillIds 绑定；输出不含执行模式字段，目录注入 Skill + Agent。',1,0,1,1,'2026-08-15 05:59:42','2026-08-15 05:59:42');
