INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('planner.harness','planner','Planner-Executor · Harness Planner','Planner 独立角色：仅叠此提示词，不叠加 mode-overlay.react；最低门槛 plan_submit→dispatch_worker→self_assess→answer；通用，不含业务示例。',1,0,1,137,'2026-08-15 06:16:19','2026-08-21 07:26:30');
