INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('routing-rule.react-compliance-risk','routing-rule','风险审查→绑定合规技能','命中风险点/合规风险审查类问法时绑定技能 compliance-review（轨 A：快速/专业模式共用；「是否合规」仍优先走 finance-smart）。',1,18,1,1,'2026-08-08 01:41:47','2026-08-13 10:24:25');
