INSERT INTO prompt_definition (id, kind, display_name, description, enabled, priority, active_version, catalog_version, created_at, updated_at) VALUES ('routing-rule.react-policy-qa','routing-rule','制度咨询→绑定政策技能','命中制度/办法/规定类咨询时绑定技能 policy-qa（轨 A：快速/专业模式共用）。',1,40,1,1,'2026-08-08 01:41:47','2026-08-13 10:24:25');
