INSERT INTO prompt_version (id, prompt_id, version, status, content_text, content_json, change_note, maintainer, created_at) VALUES (49,'timeline.steps.plan',1,'published',NULL,'{\"label\":\"执行计划\",\"before\":\"规划执行路径\",\"active\":\"正在编排业务节点顺序\",\"after\":\"执行计划已生成\"}','初始种子','agent','2026-08-08 01:41:48');
